async function applyTmdb(item,hit){item.tmdbId=String(hit.id);item.poster=hit.poster_path?'https://image.tmdb.org/t/p/w185'+hit.poster_path:'';item.backdrop=hit.backdrop_path?'https://image.tmdb.org/t/p/w780'+hit.backdrop_path:'';item.vote=Number(hit.vote_average)||0;item.pop=Number(hit.popularity)||0;item.overview=hit.overview||'';item.year=String(hit.first_air_date||'').slice(0,4)||'';if(hit.genre_ids&&hit.genre_ids.length)item.genres=hit.genre_ids.map(function(g){return genreMap[g]||''}).filter(Boolean).slice(0,3);var detail=await tmdbDetail(hit.id);if(detail&&detail.id){if(detail.genres&&detail.genres.length)item.genres=detail.genres.map(function(g){return g.name}).slice(0,3);item.status=statusMap[detail.status]||detail.status||'';item.seasons=detail.number_of_seasons||0;item.episodes=detail.number_of_episodes||0;item.lastAir=(detail.last_episode_to_air&&detail.last_episode_to_air.air_date)||detail.last_air_date||'';item.nextAir=(detail.next_episode_to_air&&detail.next_episode_to_air.air_date)||'';item.networks=(detail.networks||[]).map(function(n){return{name:n.name||'',logo:n.logo_path?'https://image.tmdb.org/t/p/w92'+n.logo_path:''}});if(!item.poster&&detail.poster_path)item.poster='https://image.tmdb.org/t/p/w185'+detail.poster_path;if(!item.backdrop&&detail.backdrop_path)item.backdrop='https://image.tmdb.org/t/p/w780'+detail.backdrop_path}if((!item.platforms||!item.platforms.length)&&item.networks&&item.networks.length)item.platforms=item.networks;if(!item.platforms||!item.platforms.length)item.platforms=await fetchPlatform(item.name,hit.id);recordTrend(item);return item}
